/* Progressive learning is based on explicit, finished attempts. It never
 * claims a heuristic method recommendation is a checked solution to a real
 * question. Original past-paper order remains available independently. */
function civilCleanStudy(raw){
 const clean={version:1,routes:{},methods:{},annotations:{}};
 if(!raw||raw.version!==1)return clean;
 const evidence=p=>p&&Number.isInteger(p.total)&&p.total>0&&p.total<=1000&&Number.isInteger(p.answered)&&p.answered>=0&&p.answered<=p.total&&Number.isFinite(p.accuracy)&&p.accuracy>=0&&p.accuracy<=100?{passed:p.passed===true,sessionId:String(p.sessionId||''),accuracy:p.accuracy,total:p.total,answered:p.answered,finishedAt:Number(p.finishedAt)||0,questionIds:Array.isArray(p.questionIds)?p.questionIds.filter(id=>typeof id==='string').slice(0,1000):[]}:null;
 for(const category of Civil.categories)for(let i=0;i<5;i++){const p=evidence(raw.routes?.[category]?.[i]);if(p){clean.routes[category]??={};clean.routes[category][i]=p;}}
 for(const m of civilMethods){const p=evidence(raw.methods?.[m.id]);if(p)clean.methods[m.id]=p;}
 for(const [id,a] of Object.entries(raw.annotations||{})){if(!['__proto__','constructor','prototype'].includes(id)&&id.length<=120&&a&&typeof a==='object')clean.annotations[id]={methods:Array.isArray(a.methods)?a.methods.filter(x=>civilMethods.some(m=>m.id===x)):[],text:String(a.text||'').slice(0,5000),updatedAt:Number(a.updatedAt)||0};}
 return clean;
}
function civilLearning(s){const info=s?.learning;return info&&(info.kind==='method'&&civilMethods.some(m=>m.id===info.method)||info.kind==='route'&&Civil.categories.includes(info.category)&&Number.isInteger(info.stage)&&info.stage>=0&&info.stage<5)?info:null;}
let civilStudy=civilCleanStudy(civilState.study);
civilStudy.routes??={};civilStudy.methods??={};civilStudy.annotations??={};civilState.study=civilStudy;
let civilRouteCategory='资料分析',civilMethodQuery='',civilCueIndex=0,civilPendingLaunch=null,civilPendingPast='';
function civilSortByDifficulty(questions){return civilGroups(questions).map((group,index)=>({group,index,level:Math.max(...group.map(q=>q.source==='知行学习室原创'?q.difficulty||q.level||2:99))})).sort((a,b)=>a.level-b.level||a.index-b.index).flatMap(item=>item.group);}
function civilSyncStudy(){const saved=civilState.study;if(saved&&saved!==civilStudy&&saved.version===1){civilStudy=civilCleanStudy(saved);civilState.study=civilStudy;}else civilState.study=civilStudy;}
const civilStageNames=['基础识别','同类巩固','变式与边界','混合限时','真题迁移'];
const civilRouteCore={政治理论:['politic-context','politic-pairs','read'],常识判断:['units','source-check','category-memory'],言语理解与表达:['central','details','fill','order'],数量关系:['equation','substitute','divisible','special'],判断推理:['definition','analogy','logic','connectors'],资料分析:['percent','ratio','base','multiple']};
const civilBadCues=[
 ['“答案字母要均匀，所以补没出现的字母”','未证明存在这一出题约束，已知答案分布不构成下一题答案的证据。','需要题目条件与推导；不要把字母频次当已验证概率优势。'],
 ['“问最大就排最小，问最少就排最大”','没有结合可行域时，最大值完全可能是最小的那个候选数。','先检验条件与上下界，再比较可行解。'],
 ['“增长量=现期×增速”','增速的基准通常是基期。现期120、增20%，增量是20而不是24。','Δ=现期×r/(1+r)。'],
 ['“基期=现期×(1−增速)”','增长与还原的分母基准不同。现期120、增20%，基期100而非96。','基期=现期/(1+r)。'],
 ['“比重提高百分点=部分增速−整体增速”','差值可判断方向，不能直接给精确幅度。','差值=本期比重×(a−b)/(1+a)。'],
 ['“涨20%再跌20%就回到原值”','两次基准不同。100→120→96。','连续变动乘因子，再减1。'],
 ['“A推出B，看到B就能推出A”','获得许可者都登记；登记者未必都获得许可。','肯前推后、否后推前；不能肯后推前。'],
 ['“看到转折，只读转折后的半句”','转折可能在例子或被批评的引用里，不一定是作者完整主张。','辨清话语层级、作者立场与整段结构。'],
 ['“元素相同一定只考位置”','图形还可能有数量、属性或复合规则。','把口诀当检索顺序，验证全部已有图。'],
 ['“所有老师的同名口诀符号都一样”','社区笔记可能把A/B对调，也可能把近似写成等式。','统一现期、基期、增速、增量的定义后再推导。']
];
const civilMethodRules=[
 {c:'资料分析',pattern:/年均|年平均增长/,ids:['annual'],reason:'包含多年年均变化线索，需核对期间数。'},
 {c:'资料分析',pattern:/平均|人均|件均|均价/,ids:['average-growth','ratio'],reason:'题干或题型包含平均量线索；先核对是否求变化率。'},
 {c:'资料分析',pattern:/间隔|连续.*(?:增长|下降)|先.*(?:增长|下降).*再/,ids:['chain-growth'],reason:'包含连续变化线索，注意变化基准。'},
 {c:'资料分析',pattern:/比重.*(?:上升|下降|提高|变化)|(?:上升|下降|提高).*比重|两期比重/,ids:['share'],reason:'包含两期比重变化线索；不是对每道题给出已验证推导。'},
 {c:'资料分析',pattern:/增长量|增加量|增加.*多少|减少.*多少|增长最多/,ids:['fraction-growth','compare-growth'],reason:'可能询问增量或增量比较；先确认给的是基期还是现期。'},
 {c:'资料分析',pattern:/基期比重|上年.*(?:占比|比重)|去年.*(?:占比|比重)/,ids:['share','base'],reason:'可能涉及基期比重，需要同时还原部分与整体，不能只还原一个量。'},
 {c:'资料分析',pattern:/基期|上年.*多少|去年.*多少/,ids:['base'],reason:'可能需要还原基期，年份与主体仍需人工确认。'},
 {c:'资料分析',pattern:/比重|占.*(?:比|%|百分)|比例/,ids:['ratio','cross'],reason:'比值类线索；缺少两期证据时不强行推荐两期比重式。'},
 {c:'资料分析',pattern:/几倍|倍数|翻番/,ids:['multiple'],reason:'倍数线索；先分清“是几倍”和“多几倍”。'},
 {c:'数量关系',pattern:/工程|工作效率|单独.*完成|合做|合作.*完成/,ids:['special','equation'],reason:'工程效率线索；真实题可能存在变速或分阶段。'},
 {c:'数量关系',pattern:/追及|相遇|相向|同向|行程/,ids:['motion'],reason:'运动线索；须核对起点、时间和速度是否恒定。'},
 {c:'数量关系',pattern:/浓度|溶液|混合.*百分/,ids:['mixture'],reason:'混合线索，先确定质量/体积口径与守恒条件。'},
 {c:'数量关系',pattern:/成本|利润|折扣|打.*折/,ids:['profit'],reason:'价格利润线索，核对百分数的基准。'},
 {c:'数量关系',pattern:/排列|组合|选出.*代表|队长.*副队长/,ids:['combination'],reason:'计数线索，需核对顺序、组别与对象可区分性。'},
 {c:'数量关系',pattern:/概率|至少一次/,ids:['probability'],reason:'概率线索，不能仅凭关键词假设独立或等可能。'},
 {c:'数量关系',pattern:/牛吃草|匀速进水|持续.*流入|检票口/,ids:['cow'],reason:'存量与持续流入线索；流入恒定等条件需另查。'},
 {c:'数量关系',pattern:/植树|路灯|间隔.*米/,ids:['plant'],reason:'等距节点线索，先判端点和闭环。'},
 {c:'数量关系',pattern:/鸡兔|条腿/,ids:['chicken'],reason:'两类对象总量线索，需确认每类单个量恒定。'},
 {c:'数量关系',pattern:/年龄|几岁|岁时/,ids:['age'],reason:'年龄线索，年龄差不变但比会变。'},
 {c:'数量关系',pattern:/保证.*(?:同色|同类|相同)|至少.*同色/,ids:['pigeon'],reason:'保证出现同类的线索，逐类容量必须检查。'},
 {c:'判断推理',pattern:/图形推理|封闭区域|对称轴|九宫格/,ids:['graph'],reason:'图形题型，仅推荐检查框架；本站没有读图识别能力。'},
 {c:'判断推理',pattern:/空间重构|六面体|折纸盒|立方体/,ids:['space','graph'],reason:'空间图形线索，真实图案方向需要人工观察。'},
 {c:'判断推理',pattern:/定义判断|根据上述定义/,ids:['definition'],reason:'题干给出定义，建议逐要件核对。'},
 {c:'判断推理',pattern:/类比推理/,ids:['analogy'],reason:'来自原题型标签，关系层级仍需自行确定。'},
 {c:'判断推理',pattern:/必要前提|必须假设|必要条件/,ids:['assumption','logic'],reason:'前提题线索；必要性与一般加强不同。'},
 {c:'判断推理',pattern:/加强|削弱|论证/,ids:['argument','causal'],reason:'论证线索，不代表全部题目都是因果论证。'},
 {c:'判断推理',pattern:/只有|除非|否则|翻译推理/,ids:['connectors','logic'],reason:'条件命题线索，注意否定与方向。'},
 {c:'判断推理',pattern:/恰有.*真|恰好.*真|真假推理/,ids:['truth'],reason:'真假数量约束线索，先核对是否存在严格矛盾对。'},
 {c:'言语理解与表达',pattern:/逻辑填空|填入.*最恰当|填入.*最合适/,ids:['fill'],reason:'填空题线索，先看语境约束。'},
 {c:'言语理解与表达',pattern:/语句排序|排列.*语序|重新排列/,ids:['order'],reason:'排序线索，先绑定再验证全篇。'},
 {c:'言语理解与表达',pattern:/细节判断|符合文意|不符合文意/,ids:['details','word-scope'],reason:'细节题线索，需回文核对具体限定。'},
 {c:'言语理解与表达',pattern:/中心理解|主旨|主要.*(?:强调|说明|意在)|意在/,ids:['central','discourse'],reason:'主旨线索，避免只概括局部例证。'}
];
function civilStudySave(){civilState.study=civilStudy;civilPersist();}
function civilRecommendations(q){const saved=civilStudy.annotations[q.id];if(Array.isArray(saved?.methods)&&saved.methods.length)return {ids:saved.methods.filter(id=>civilMethods.some(m=>m.id===id)),kind:'手动标注',reason:'这是你保存的方法关联，可继续修订。',text:String(saved.text||'')};if(q.method&&civilMethods.some(m=>m.id===q.method))return {ids:[q.method],kind:'原创配套',reason:'本站编写题目时关联的方法。',text:''};const text=(q.subtype||'')+' '+q.stem.replace(/<[^>]+>/g,' ');const rule=civilMethodRules.find(r=>r.c===q.category&&r.pattern.test(text));return rule?{ids:rule.ids,kind:'题型建议 · 未逐题核验',reason:rule.reason,text:String(saved?.text||'')}:{ids:[],kind:'待标注',reason:'没有足够可靠的题型线索，先阅读原解析；不为这道题猜口诀或编造快解。',text:String(saved?.text||'')};}
function civilMethodQuestions(id,level){return [...civilBank.values()].filter(q=>q.source==='知行学习室原创'&&q.method===id&&(level===undefined||q.level===level));}
function civilStagePassed(category,index){const p=civilStudy.routes[category]?.[index];return !!p&&p.passed&&p.accuracy>=80&&p.answered===p.total&&p.total>0;}
function civilStageUnlocked(category,index){return index===0||[...Array(index).keys()].every(i=>civilStagePassed(category,i));}
function civilRouteQueue(category,index){let pool=[...civilBank.values()].filter(q=>q.category===category&&!civilLookup(q.id)?.reviewRequired);if(index===4)return civilPick(pool.filter(q=>q.source==='ERRRC/xingcezhenti'),20,false);pool=pool.filter(q=>q.source==='知行学习室原创');if(index===0){const core=civilRouteCore[category];return civilPick(pool.filter(q=>core.includes(q.method)&&q.level===1),6,false);}if(index===1){const focus=$('civil-route-focus')?.value||civilRouteCore[category][0];return civilPick(pool.filter(q=>q.method===focus),Math.min(8,pool.filter(q=>q.method===focus).length),false);}if(index===2)return civilPick(pool.filter(q=>q.level>=2),10,true,category+':variation');return civilPick(pool,15,true,category+':mixed');}
function civilLaunchRoute(category,index){if(!civilStageUnlocked(category,index))return toast('先通过前一阶段：完成全部题目且正确率达到80%。');if(index===4){const qs=civilRouteQueue(category,index);if(qs.length<5){civilPendingPast=category;civilGo('papers');toast('先载入该模块至少5道有明确答案的真题，再回进阶路线开始迁移练习。');return;}}const questions=civilRouteQueue(category,index);if(!questions.length)return toast('没有足够题目，先换一个方法或载入题库。');const mode=index>=2?'exam':'practice',minutes=Math.max(3,Math.ceil(questions.length*(category==='数量关系'?2:1.5)));civilPendingLaunch={kind:'route',category,stage:index,questionIds:questions.map(q=>q.id),minimum:questions.length};civilStart(questions,mode,minutes,category+' · '+civilStageNames[index]);}
function civilAttemptEvidence(s){const info=civilLearning(s);if(!s?.finished||!info)return;const report=Civil.report(s,id=>civilBank.get(id));const answered=report.right+report.wrong,passed=report.ungraded===0&&report.blank===0&&answered===report.total&&report.accuracy>=80;const result={passed,sessionId:s.id,accuracy:report.accuracy,total:report.total,answered,finishedAt:s.finishedAt,questionIds:[...s.questions]};if(info.kind==='method'){civilStudy.methods[info.method]=result;}else if(info.kind==='route'){const index=info.stage;if(civilStageUnlocked(info.category,index)){civilStudy.routes[info.category]??={};const previous=civilStudy.routes[info.category][index];if(!previous?.passed||passed)civilStudy.routes[info.category][index]=result;}}civilStudySave();}
const studyStartBase=civilStart,studyFinishBase=civilFinish;
civilStart=function(questions,mode,minutes,label,replace){const before=civilSession()?.id;studyStartBase(questions,mode,minutes,label,replace);if(civilSession()?.id!==before&&civilPendingLaunch&&questions.map(q=>q.id).join('|')===civilPendingLaunch.questionIds.join('|')){civilSession().learning={...civilPendingLaunch};civilPendingLaunch=null;civilStudySave();render();}};
civilFinish=function(){const s=civilSession(),was=s?.finished;studyFinishBase();if(s&&!was&&s.finished){civilAttemptEvidence(s);if(view==='civil')render();}};
function civilRouteHTML(){const category=civilRouteCategory,progress=civilStudy.routes[category]||{},counts=civilMethods.filter(m=>m.category===category).length;return `<section class="section"><div class="eyebrow">按学习证据前进 / 独立于原卷目录</div><h2>先学会一种方法，再把它用进套卷。</h2><p>原卷仍保留题目顺序。这条学习路线按“识别 → 同类 → 变式 → 混合 → 真题”组织。各阶段完成全部题、正确率达到80%后，手动进入下一阶段；这是本站练习门槛，不是官方分数。</p><div class="civil-controls civil-route-controls"><label>学习模块<select id="civil-route-category">${Civil.categories.map(c=>`<option ${c===category?'selected':''}>${c}</option>`).join('')}</select></label><label>同类巩固的目标方法<select id="civil-route-focus">${civilMethods.filter(m=>m.category===category||civilRouteCore[category].includes(m.id)).map(m=>`<option value="${m.id}">${m.title}</option>`).join('')}</select></label></div><p>${category}有 ${counts} 张专题方法卡；全模块另有审题与复盘课。题目难度标签由本站编写，未擅自给全量真题标难度。</p></section><div class="civil-route-list">${civilStageNames.map((name,i)=>{const unlocked=civilStageUnlocked(category,i),done=civilStagePassed(category,i),p=progress[i];const desc=['圈主体、时期、单位，识别公式或推理规则。','选定一个方法，连续完成同类应用并回查条件。','加入变化条件与易错边界，在自定义时限内作答。','混合本模块多种题型，练习方法选择与时间分配。','使用本设备已载入的真实试卷题，保留原解析与来源。'][i];return `<article class="section civil-route-card ${done?'passed':''}"><span class="path-number">0${i+1}</span><div><span class="chip">${done?'已通过':unlocked?'可开始':'待解锁'}</span><h2>${name}</h2><p>${desc}</p>${p?`<p>最近有效记录：${p.accuracy}% · 完成 ${p.answered}/${p.total} · ${p.passed?'通过':'继续巩固'}</p>`:''}</div><button class="${unlocked?'primary':'secondary'}" data-study="route-start" data-stage="${i}" ${unlocked?'':'disabled'}>${done?'再练一次':i===4?'开始真题迁移':'开始本阶段'}</button></article>`;}).join('')}</div><section class="section"><h2>先学哪些方法？</h2><div class="filter-tabs">${civilRouteCore[category].map(id=>`<button data-civil="method" data-id="${id}">${civilMethods.find(m=>m.id===id).title}</button>`).join('')}</div><button class="secondary" data-civil="pane" data-id="methods">查看完整方法课与口诀</button></section>`;}
function civilCoverageHTML(){const groups={'原创配套':0,'手动标注':0,'题型建议 · 未逐题核验':0,'待标注':0},pending=[];for(const q of civilBank.values()){const rec=civilRecommendations(q);groups[rec.kind]++;if(q.source==='ERRRC/xingcezhenti'&&!rec.ids.length)pending.push(q);}return `<section class="section"><h2>题库与方法关联覆盖</h2><p>只统计本设备已载入的题目。题型匹配不是已核验解法，无法可靠匹配的题目明确留待标注。</p><div class="civil-summary">${Object.entries(groups).map(([name,n])=>`<div><small>${name}</small><b>${n}</b></div>`).join('')}</div>${pending.length?`<details><summary>待标注真题 ${pending.length} 道 · 查看前20道</summary>${pending.slice(0,20).map(q=>`<article class="civil-history"><div><b>${esc(q.paper)}</b><p>${esc(q.subtype)} · qid ${esc(q.qid)}</p></div><button class="secondary" data-civil="inspect" data-id="${q.id}">读原解析并标注方法</button></article>`).join('')}</details>`:'<p>当前没有未关联方法的已载入真题；这不代表全库已逐题核验。</p>'}<p class="small-note">全库仍可按515套原卷目录读取；完整课程或教师独家资料的归属与授权不因自动匹配而改变。</p></section>`;}
function civilCueHTML(){const list=civilMethods.filter(m=>(civilMethodCategory==='全部'||m.category===civilMethodCategory)&&(civilMethodTier==='全部'||m.tier===civilMethodTier)&&(!civilMethodQuery||(m.title+m.mnemonic+m.formula+m.when+(m.aliases||[]).join('')).includes(civilMethodQuery)));return `<section class="section"><h2>口诀速记：提示路径，不代替推理。</h2><p>每句助记都能展开条件、公式、反例和训练。这里的助记由本站独立整理，不冒称名师原话。</p>${civilMethodFilters()}<div class="civil-cue-grid">${list.map(m=>`<details class="civil-cue"><summary><span class="chip">${m.tier} · ${m.category}</span><h3>${m.title}</h3><b>${m.mnemonic}</b></summary><p>适用：${m.when}</p><pre>${esc(m.formula)}</pre><p>边界：${m.risk}</p><p>例子：${m.example}</p><button class="primary" data-civil="method" data-id="${m.id}">展开完整课与分层练习</button></details>`).join('')}</div></section><section class="section"><h2>这些“秒杀口诀”不能照单全收</h2><div class="civil-bad-cues">${civilBadCues.map(r=>`<article><h3>${r[0]}</h3><p>${r[1]}</p><p><b>正确做法：</b>${r[2]}</p></article>`).join('')}</div></section>`;}
function civilMethodFilters(){return `<div class="civil-controls"><label>阶段<select id="civil-method-tier">${['全部','基础','熟练','进阶'].map(v=>`<option ${civilMethodTier===v?'selected':''}>${v}</option>`).join('')}</select></label><label>科目<select id="civil-method-category">${['全部','全模块',...Civil.categories].map(v=>`<option ${civilMethodCategory===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="grow">方法、口诀或公式<input id="civil-method-query" value="${esc(civilMethodQuery)}" placeholder="如 多一份、两期比重、只有、尾数"></label><button class="secondary" data-study="method-search">查找</button></div>`;}
const studyMethodBase=civilMethodsHTML,studyExplanationBase=civilExplanationHTML,studyReportBase=civilReportHTML,studyHomeBase=civilHomeHTML,studyShellBase=civilShell,studyRenderBase=render,studyStatsBase=civilStatsHTML;
civilStatsHTML=function(){return studyStatsBase()+civilCoverageHTML();};
civilMethodsHTML=function(){if(!civilMethodId){const list=civilMethods.filter(m=>(civilMethodTier==='全部'||m.tier===civilMethodTier)&&(civilMethodCategory==='全部'||m.category===civilMethodCategory)&&(!civilMethodQuery||(m.title+m.mnemonic+m.formula+m.when+(m.aliases||[]).join('')).includes(civilMethodQuery))).sort((a,b)=>['基础','熟练','进阶'].indexOf(a.tier)-['基础','熟练','进阶'].indexOf(b.tier)||a.order-b.order);return `<section class="section"><h2>${civilMethods.length} 张方法课：认条件、会推导、再提速</h2><p>每课都有助记、标准过程、快解与边界，并配识别、应用、变式辨析三层原创题。读完与独立通过分开记录。</p><div class="hero-actions"><button class="primary" data-civil="pane" data-id="route">进入进阶练习路线</button><button class="secondary" data-civil="pane" data-id="cues">打开口诀速记</button></div>${civilMethodFilters()}</section><div class="civil-method-grid">${list.map(m=>`<button class="section civil-method-card" data-civil="method" data-id="${m.id}"><span class="chip">${m.tier} · ${m.category}</span><h3>${m.title}</h3><p>${m.mnemonic}</p><small>${civilStudy.methods[m.id]?.passed?'✓ 独立小测通过':civilState.methods.includes(m.id)?'已读，待独立验证':'未读'} · ${civilMethodQuestions(m.id).length} 道配套题</small></button>`).join('')}</div>`;}
 const m=civilMethods.find(m=>m.id===civilMethodId),base=studyMethodBase()+(m.extraLesson?'<section class="section"><h2>常见叫法与等价推导</h2><p>'+esc(m.extraLesson)+'</p><p class="small-note">相关名称来自公开资料线索；讲解为本站独立整理，不复刻整套教师课程。</p></section>':''),application=civilMethodQuestions(m.id,2).find(q=>q.id.startsWith('train-')),boundary=civilMethodQuestions(m.id,3)[0];return base.replace('<h2>'+m.title+'</h2>','<h2>'+m.title+'</h2>'+`<section class="civil-memory-card"><small>本站原创助记 · 通用方法</small><h3>${m.mnemonic}</h3><p>触发条件：${m.when}</p><p>核对条件：${m.cueCondition}</p></section>`).replace('<h3>什么时候用</h3>',`<h3>先备知识</h3><div class="filter-tabs">${m.prerequisites.map(id=>`<button data-civil="method" data-id="${id}">${civilMethods.find(x=>x.id===id)?.title||id}</button>`).join('')||'<span>可直接从本课开始。</span>'}</div><h3>什么时候用</h3>`)+`<section class="section"><h2>把方法用出来</h2>${application?`<details><summary>引导例题 · 展开后不计独立作答</summary><div>${civilHTML(application.stem)}</div><p>${esc(application.explanation)}</p></details>`:''}${boundary?`<details><summary>反例与边界 · 为什么口诀不能硬套</summary><div>${civilHTML(boundary.stem)}</div><p>${esc(boundary.explanation)}</p></details>`:''}<div class="civil-layer-actions">${[[1,'基础识别'],[2,'同类应用'],[3,'边界变式']].map(([level,title])=>`<button class="secondary" data-study="method-level" data-id="${m.id}" data-level="${level}">${title} · ${civilMethodQuestions(m.id,level).length}题</button>`).join('')}<button class="primary" data-study="method-check" data-id="${m.id}">三层混合小测 · 独立验证</button></div><p>全部题目完成、正确率达到80%后记录小测通过；单层练习用于巩固。</p><p class="small-note">${m.provenance}</p></section>`;};
function civilRecommendHTML(q,editing=true){const rec=civilRecommendations(q),saved=civilStudy.annotations[q.id]||{};return `<section class="civil-method-link"><span class="chip">${rec.kind}</span><h3>把这题连接到方法课</h3><p>${rec.reason}</p>${rec.ids.map(id=>{const m=civilMethods.find(x=>x.id===id);return `<article><b>${m.title}</b><p>助记：${m.mnemonic}</p><p>先检查：${m.when}</p><p>不能硬套：${m.risk}</p><button class="secondary" data-civil="method" data-id="${m.id}">回看推导、例题与训练</button></article>`;}).join('')}${rec.text?`<div class="worked-example"><b>你的补充解法（用户笔记）</b><p>${esc(rec.text)}</p></div>`:''}${editing?`<details><summary>手动核对方法并补充本题解法</summary><label for="civil-link-method">确认的方法<select id="civil-link-method"><option value="">不确定，保留待标注</option>${civilMethods.map(m=>`<option value="${m.id}" ${saved.methods?.includes(m.id)?'selected':''}>${m.category} · ${m.title}</option>`).join('')}</select></label><label for="civil-link-text">写出本题的条件、列式和关键一步</label><textarea id="civil-link-text" rows="4" maxlength="5000">${esc(saved.text||'')}</textarea><button class="primary" data-study="save-link" data-id="${q.id}">保存本题方法与笔记</button><p class="small-note">这是个人核对记录，保持原解析独立，不标成名师原话或本站人工认证。</p></details>`:''}</section>`;}
civilExplanationHTML=function(q){return studyExplanationBase(q)+civilRecommendHTML(q);};
civilReportHTML=function(){const base=studyReportBase(),s=civilSession();if(!s?.finished)return base;const info=civilLearning(s),report=Civil.report(s,id=>civilBank.get(id));const evidence=info?{passed:report.accuracy>=80&&report.blank===0&&report.ungraded===0,accuracy:report.accuracy}:null;const wrongMethods=[...new Set(s.questions.filter(id=>['wrong','blank'].includes(s.submitted[id]?.result)).flatMap(id=>civilBank.get(id)?civilRecommendations(civilBank.get(id)).ids:[]))];return base+(info?`<section class="section"><h2>${evidence.passed?'✓ 本次学习验证通过':'本次仍需巩固'}</h2><p>${info.kind==='route'?info.category+' · '+civilStageNames[info.stage]:'方法：'+civilMethods.find(m=>m.id===info.method)?.title} · 完成率与正确率均按本次记录判断。</p>${info.kind==='route'&&evidence.passed&&info.stage<4?`<button class="primary" data-study="next-route" data-category="${info.category}" data-stage="${info.stage+1}">手动进入下一阶段</button>`:''}<button class="secondary" data-civil="pane" data-id="route">查看进阶路线与记录</button></section>`:'')+(wrongMethods.length?`<section class="section"><h2>下一步先补这些方法</h2><div class="filter-tabs">${wrongMethods.map(id=>`<button data-civil="method" data-id="${id}">${civilMethods.find(m=>m.id===id).title}</button>`).join('')}</div><p class="small-note">题型匹配的方法是复习建议，未代替逐题人工判断。</p></section>`:'');};
civilHomeHTML=function(){return `<section class="civil-resume"><div><b>从知识点走到完整套卷</b><p>${civilMethods.length}张方法课 · 原创分层训练 · 口诀与反例 · 真题方法关联</p></div><button class="primary" data-civil="pane" data-id="route">按进阶路线学习</button><button class="secondary" data-civil="pane" data-id="cues">查口诀</button></section>`+studyHomeBase();};
civilShell=function(content){return studyShellBase(content).replace('<button data-civil="pane" data-id="methods"',`<button data-civil="pane" data-id="route" class="${civilPane==='route'?'active':''}">进阶路线</button><button data-civil="pane" data-id="cues" class="${civilPane==='cues'?'active':''}">口诀速记</button><button data-civil="pane" data-id="methods"`).replace('<h1>考公刷题</h1>',civilPane==='route'?'<h1>从基础到真题的进阶路线</h1>':civilPane==='cues'?'<h1>口诀、快解与使用边界</h1>':'<h1>考公刷题</h1>');};
render=function(){civilSyncStudy();if(view==='civil'&&['route','cues'].includes(civilPane)){const s=civilSession();if(s&&!s.finished&&!s.paused&&s.mode==='practice'){Civil.recordTime(s);s.paused=true;civilPersist();}$('app').innerHTML=hubNav()+civilShell(civilPane==='route'?civilRouteHTML():civilCueHTML());const bar=document.querySelector('.subject-bar');if(bar){const wrap=document.createElement('details'),summary=document.createElement('summary');wrap.className='classroom-switcher civil-switcher';summary.textContent='考公刷题 · 切换学习领域';bar.before(wrap);wrap.append(summary,bar);}return;}studyRenderBase();if(view==='civil'&&civilPane==='papers'&&civilPendingPast){for(const select of document.querySelectorAll('[id^="paper-module-"]')){if([...select.options].some(o=>o.value===civilPendingPast))select.value=civilPendingPast;}}};
document.addEventListener('change',e=>{if(e.target.id==='civil-route-category'){civilRouteCategory=e.target.value;render();}});
document.addEventListener('click',e=>{const el=e.target.closest('[data-study]'),base=e.target.closest('[data-civil]');if(base?.dataset.civil==='close-dialog')civilPendingLaunch=null;if(!el||el.disabled)return;const d=el.dataset;try{if(d.study==='method-search'){civilMethodQuery=$('civil-method-query').value.trim();render();}if(d.study==='route-start')civilLaunchRoute(civilRouteCategory,Number(d.stage));if(d.study==='next-route'){civilRouteCategory=d.category;civilGo('route');}if(d.study==='method-level'||d.study==='method-check'){const level=d.study==='method-level'?Number(d.level):undefined,questions=civilMethodQuestions(d.id,level);civilPendingLaunch=level===undefined?{kind:'method',method:d.id,questionIds:questions.map(q=>q.id)}:null;civilStart(questions,level===undefined?'exam':'practice',Math.max(3,Math.ceil(questions.length*1.5)),civilMethods.find(m=>m.id===d.id).title+' · '+(level===undefined?'三层小测':['','识别','应用','边界'][level]));}if(d.study==='save-link'){const method=$('civil-link-method').value,text=$('civil-link-text').value;civilStudy.annotations[d.id]={methods:method?[method]:[],text,updatedAt:Date.now()};civilStudySave();const section=document.querySelector('.civil-method-link'),q=civilBank.get(d.id);if(section&&q)section.outerHTML=civilRecommendHTML(q);toast('本题方法与个人解法已保存，原解析保持独立。');}}catch(error){toast(error.message);}});
// Old cached questions gain recommendations at render time; no bulk migration
// or claim of AI-generated per-question solutions is necessary.
civilState.study=civilStudy;render();
